head.script:
// https://inswave01.atlassian.net/browse/WAEA-1388



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > E > onchange]<br/>DatePicker 컴포넌트의 선택 날짜가 변경되면 발생합니다.",
    "validation" : [
        "DatePicker 컴포넌트의 선택 날짜가 변경되면 onchange 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 - ref 로 DataMap 에 바인딩 (setValue 를 호출하지 않아 바인딩 값으로만 초기화)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] ref = data:dma_ref.key1 (바인딩 초기값 20251111)\n[확인] Target 재생성 시 바인딩 값으로 날짜가 표시될 때와 DataMap 값 변경 버튼 클릭 시 onchange 출력"', '', 'label1');

    // 바인딩 초기값 복원
    dma_ref.set("key1", "20251111");

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let eList = $c.gcm.createEList(["onchange"]);

    let strTarget = '<w2:datePicker ' + strNameSpace + ' ref="data:dma_ref.key1" ' + eList + ' id="" style="width:300px; height:200px; position:relative;"></w2:datePicker>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "datePicker",
        strTarget,
        grp_comp
    );
};



// 바인딩된 DataMap 값 변경
scwin.btn_dataSet_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[DataMap 값 변경] key1 = 20261012");
    dma_ref.set("key1", "20261012");
};



// 선택 날짜가 변경되면 발생 - validation 1 판정 출력
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생] getValue : " + target1.getValue());
};
